def kernels_by_category(category: str) -> list[KernelInfo]:
    return [kernel for kernel in KERNELS if kernel.category == category]

def by_canonical_name(name: str) -> KernelInfo:
    for kernel in KERNELS:
        if kernel.canonical_name == name:
            return kernel
    raise KeyError(name)
